#!/bin/sh
set -eu
# Inputs and payloads stay outside Git at /tmp/lz-sparse-audit.
for x in sparse:11 runs:12; do n=${x%:*}; m=${x#*:}; perl packetraw/frame.pl "$m" /tmp/lz-sparse-audit/in "/tmp/lz-sparse-audit/c.$n" > "/tmp/lz-sparse-audit/$n.fresh.m6"; /tmp/cix-lz-sparse-d52/rust/cix-native/target/debug/uncix -f -o "/tmp/lz-sparse-audit/$n.fresh.out" "/tmp/lz-sparse-audit/$n.fresh.m6" >"/tmp/lz-sparse-audit/$n.fresh.stdout" 2>"/tmp/lz-sparse-audit/$n.fresh.stderr"; printf '%s success rc=%s\n' "$n" "$?"; cp "/tmp/lz-sparse-audit/$n.fresh.m6" "/tmp/lz-sparse-audit/$n.fresh.trunc"; truncate -s -1 "/tmp/lz-sparse-audit/$n.fresh.trunc"; if /tmp/cix-lz-sparse-d52/rust/cix-native/target/debug/uncix -f -o "/tmp/lz-sparse-audit/$n.fresh.bad" "/tmp/lz-sparse-audit/$n.fresh.trunc" >"/tmp/lz-sparse-audit/$n.fresh.trunc.stdout" 2>"/tmp/lz-sparse-audit/$n.fresh.trunc.stderr"; then exit 1; else printf '%s trunc rc=%s\n' "$n" "$?"; fi; sha256sum /tmp/lz-sparse-audit/in "/tmp/lz-sparse-audit/c.$n" "/tmp/lz-sparse-audit/$n.fresh.m6" "/tmp/lz-sparse-audit/$n.fresh.out"; done
